import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.C-si7TFR.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"trigger_telegram_bot_old.md","filePath":"trigger_telegram_bot_old.md"}'),i={name:"trigger_telegram_bot_old.md"};function n(s,e,l,c,h,u){return a(),r("div",null,[...e[0]||(e[0]=[o('<h2 id="indroduction" tabindex="-1">Indroduction <a class="header-anchor" href="#indroduction" aria-label="Permalink to &quot;Indroduction&quot;">​</a></h2><p>The telegram bot trigger supports setting keywords to respond.</p><blockquote><p>Historical interface images are withheld pending review and recapture. Check operations against the current interface.</p></blockquote><h2 id="how-to-use" tabindex="-1">How To Use <a class="header-anchor" href="#how-to-use" aria-label="Permalink to &quot;How To Use&quot;">​</a></h2><h3 id="_1-create-telegram-credential-access-token" tabindex="-1">1. Create telegram credential [Access Token] <a class="header-anchor" href="#_1-create-telegram-credential-access-token" aria-label="Permalink to &quot;1. Create telegram credential [Access Token]&quot;">​</a></h3><p>If the <strong>[Default Cred]</strong> switch is enabled, then there is no need to manually select the credentials when editing the telegram bot app, the system will automatically select the default credentials.</p><p><strong>Remark</strong>: how to create telegram bot and get access token , please refer to <a href="./how_to_create_telegram_bot_and_get_token.html">How to create telegram bot and get token</a></p><blockquote><p>Historical interface images are withheld pending review and recapture. Check operations against the current interface.</p></blockquote><p>If enable the <strong>[Default Cred]</strong> above, then no need manually select.</p><blockquote><p>Historical interface images are withheld pending review and recapture. Check operations against the current interface.</p></blockquote><h3 id="_2-configure-message-type" tabindex="-1">2. Configure [Message Type] <a class="header-anchor" href="#_2-configure-message-type" aria-label="Permalink to &quot;2. Configure [Message Type]&quot;">​</a></h3><blockquote><p>Historical interface images are withheld pending review and recapture. Check operations against the current interface.</p></blockquote><ul><li><p>Text</p><p>Set specific keywords to respond, such as <strong>/start</strong> or <strong>help</strong>, etc.</p></li></ul><blockquote><p>Historical interface images are withheld pending review and recapture. Check operations against the current interface.</p></blockquote><ul><li>Event <ul><li>Enter Group Event</li><li>Exit Group Event</li></ul></li></ul><blockquote><p>Historical interface images are withheld pending review and recapture. Check operations against the current interface.</p></blockquote><h3 id="_3-configure-monitor-users" tabindex="-1">3. Configure <strong>[Monitor Users]</strong> <a class="header-anchor" href="#_3-configure-monitor-users" aria-label="Permalink to &quot;3. Configure **[Monitor Users]**&quot;">​</a></h3><p>If it is not set by default, any user&#39;s message to the telegram robot will trigger a response as long as it hits the rule.</p><p>If you only want the robot&#39;s command response to be used only by yourself, you can select your own account from the drop-down list.</p><p>Remark: Please remember to associate your userid and admin account on telegram: <a href="./how_to_get_telegram_userid_by_iolinker.html">How to get telegram userid and associate it to admin account</a></p><blockquote><p>Historical interface images are withheld pending review and recapture. Check operations against the current interface.</p></blockquote><h3 id="_4-configure-keyword" tabindex="-1">4. Configure [Keyword] <a class="header-anchor" href="#_4-configure-keyword" aria-label="Permalink to &quot;4. Configure [Keyword]&quot;">​</a></h3><ul><li><p>Exact Match</p><p>Only when the message sent by the user exactly equal to the keyword, the workflow will be triggered to response.</p></li><li><p>Fuzzy Match</p><p>As long as the content of the message sent by the user contains the set keywords,the workflow will be triggered to response.</p></li><li><p>Regex Match</p><p>You can match the message sent by the user by configure a regular expression, as long as it hits, the workflow will be triggered to response.</p></li></ul><blockquote><p>Historical interface images are withheld pending review and recapture. Check operations against the current interface.</p></blockquote><h3 id="_5-set-debug-data" tabindex="-1">5. Set [Debug Data] <a class="header-anchor" href="#_5-set-debug-data" aria-label="Permalink to &quot;5. Set [Debug Data]&quot;">​</a></h3><p>[Debug Data] is used to simulate the parameters passed by user message, which is for easy debugging.</p><h3 id="_6-demo-exact-match-text" tabindex="-1">6. Demo [Exact Match Text] <a class="header-anchor" href="#_6-demo-exact-match-text" aria-label="Permalink to &quot;6. Demo [Exact Match Text]&quot;">​</a></h3><h4 id="_6-1-create-telegram-bot-workflow" tabindex="-1">6.1 Create telegram bot workflow <a class="header-anchor" href="#_6-1-create-telegram-bot-workflow" aria-label="Permalink to &quot;6.1 Create telegram bot workflow&quot;">​</a></h4><p>This is the telegram bot we created.</p><blockquote><p>Historical interface images are withheld pending review and recapture. Check operations against the current interface.</p></blockquote><h4 id="_6-2-enable-telegram-bot-workflow" tabindex="-1">6.2 Enable telegram bot workflow <a class="header-anchor" href="#_6-2-enable-telegram-bot-workflow" aria-label="Permalink to &quot;6.2 Enable telegram bot workflow&quot;">​</a></h4><p>You can enable it in [ChatBot List] or in [Workflow List] page.</p><blockquote><p>Historical interface images are withheld pending review and recapture. Check operations against the current interface.</p></blockquote><h4 id="_6-3-send-message-to-telegram-bot-in-telegram-app" tabindex="-1">6.3 Send message to telegram bot in telegram app <a class="header-anchor" href="#_6-3-send-message-to-telegram-bot-in-telegram-app" aria-label="Permalink to &quot;6.3 Send message to telegram bot in telegram app&quot;">​</a></h4><blockquote><p>Historical interface images are withheld pending review and recapture. Check operations against the current interface.</p></blockquote><h4 id="_6-4-find-the-execution-detail" tabindex="-1">6.4 Find the execution detail <a class="header-anchor" href="#_6-4-find-the-execution-detail" aria-label="Permalink to &quot;6.4 Find the execution detail&quot;">​</a></h4><p>You can see the execution in [Execution List], and the message sent by user.</p><blockquote><p>Historical interface images are withheld pending review and recapture. Check operations against the current interface.</p></blockquote><blockquote><p>The user messages that meet the matching rules pulled from the telegram api will be used as the output of the <strong>[Telegram Bot Trigger]</strong> app.</p></blockquote><blockquote><p>Historical interface images are withheld pending review and recapture. Check operations against the current interface.</p></blockquote>',40)])])}const p=t(i,[["render",n]]);export{g as __pageData,p as default};
